// In-memory fictional fixtures. Production checklists are generated by the site worker.
import type {
  Checklist,
  ChecklistContent,
  Workspace,
} from "../features/safety/api";
type Row = Record<string, unknown>;
interface State {
  created: number;
  checklist: Checklist | null;
  replaced: boolean;
  replaceAt?: number;
}
const states = new Map<string, State>();
const receipts = new Set<string>();
const scenario = () => new URLSearchParams(location.search).get("safety") ?? "";
function content(): ChecklistContent {
  const missing = scenario() === "missing";
  const now = new Date().toISOString();
  const quote =
    "FICTIONAL DEMO: review water, shade and current site alerts before work.";
  return {
    summary:
      "FICTIONAL DEMO ONLY: this example is not an approved employer procedure or a real regulatory finding.",
    jurisdiction: {
      state: missing ? null : "Florida",
      state_code: missing ? null : "FL",
      county: missing ? null : "Alachua County",
      city: missing ? null : "Gainesville city",
      resolved: !missing,
      source_url: "https://geocoding.geo.census.gov/",
    },
    conditions: missing
      ? []
      : [
          {
            id: 1,
            hazard: "heat",
            value: 92,
            unit: "heat_index_f",
            observed_at:
              scenario() === "stale"
                ? new Date(Date.now() - 10800000).toISOString()
                : now,
            forecast_for: "-infinity",
            source: "fictional fixture",
          },
        ],
    alerts: [],
    items: missing
      ? []
      : scenario() === "long"
        ? Array.from({ length: 12 }, (_, i) => ({
            id: `item-${i + 1}`,
            kind: "guidance" as const,
            title: `FICTIONAL DEMO action ${i + 1}`,
            text: quote.repeat(20),
            conditions: "Fictional scope details. ".repeat(20),
            citations: [{ source_id: "source-1", quote: quote.repeat(20) }],
          }))
        : [
            {
              id: "item-1",
              kind: "guidance",
              title: "FICTIONAL DEMO heat precautions",
              text: quote,
              conditions: "Fictional demonstration only.",
              citations: [{ source_id: "source-1", quote }],
            },
          ],
    sources: missing
      ? []
      : [
          {
            id: "source-1",
            title: "FICTIONAL DEMO safety guidance",
            url: "",
            level: "federal",
            jurisdiction: "Fictional example",
            checked_at: now,
          },
        ],
    coverage_gaps: [
      missing
        ? "Jurisdiction lookup and official sources unavailable; this does not mean there are no requirements."
        : "FICTIONAL DEMO ONLY. This example does not establish regulatory coverage.",
    ],
  };
}
function checklist(date: string): Checklist {
  return {
    id: crypto.randomUUID(),
    work_date: date,
    content: content(),
    generated_at: new Date().toISOString(),
    valid_until: new Date(Date.now() + 3600000).toISOString(),
    current: scenario() !== "stale",
    acknowledged: false,
  };
}
function get(site: string, date: string) {
  const key = `${site}:${date}`;
  let state = states.get(key);
  if (!state) {
    state = {
      created: Date.now(),
      checklist: ["published", "stale", "revised", "retry"].includes(scenario())
        ? checklist(date)
        : null,
      replaced: false,
    };
    states.set(key, state);
  }
  return state;
}
function response(value: unknown, status = 200) {
  return new Response(JSON.stringify(value), {
    status,
    headers: { "content-type": "application/json" },
  });
}
const error = (message: string, status = 400) =>
  response({ message, code: "SAFETY_DEMO" }, status);
export function handleSafety(
  path: string,
  body: Row,
  email: string,
  memberSites: string[],
  _supervisor: boolean,
  fail: boolean,
): Response | undefined {
  const name = path.replace("/rest/v1/rpc/", "");
  if (
    ![
      "get_automatic_safety_workspace",
      "acknowledge_automatic_safety_checklist",
    ].includes(name)
  )
    return;
  if (name === "get_automatic_safety_workspace") {
    const site = String(body.p_site_id ?? ""),
      date = String(body.p_work_date ?? "");
    if (!memberSites.includes(site))
      return error("Site membership required", 403);
    const state = get(site, date),
      mode = scenario();
    if (state.replaceAt && Date.now() > state.replaceAt && !state.replaced) {
      state.checklist = checklist(date);
      state.replaced = true;
    }
    const waiting = ["pending", "retry", "failed", "disabled"].includes(mode);
    if (!state.checklist && !waiting && Date.now() - state.created > 700)
      state.checklist = checklist(date);
    const data: Workspace = {
      enabled: mode !== "disabled",
      checklist: state.checklist
        ? {
            ...state.checklist,
            acknowledged: receipts.has(`${email}:${state.checklist.id}`),
          }
        : null,
      run: {
        state:
          mode === "failed"
            ? "failed"
            : mode === "retry" || mode === "pending" || !state.checklist
              ? "queued"
              : "succeeded",
        attempt: mode === "retry" ? 2 : 1,
        error_category:
          mode === "failed"
            ? "provider_unavailable"
            : mode === "retry"
              ? "provider_rate_limited"
              : null,
      },
    };
    return response(data);
  }
  if (fail) return error("Simulated safety write failure", 500);
  const entry = [...states.entries()].find(
    ([, state]) => state.checklist?.id === body.p_checklist_id,
  );
  if (!entry) return error("Checklist no longer current");
  const [key, state] = entry;
  if (!memberSites.includes(key.split(":")[0]))
    return error("Site membership required", 403);
  if (!state.checklist?.current) return error("Checklist no longer current");
  receipts.add(`${email}:${state.checklist.id}`);
  if (scenario() === "revised" && !state.replaced)
    state.replaceAt = Date.now() + 1000;
  return response(null);
}
